from solution import fix_spaces
import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st


def reference_fix_spaces(text):
    res = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != ' ':
            res.append(text[i])
            i += 1
        else:
            j = i
            while j < n and text[j] == ' ':
                j += 1
            run = j - i
            if run == 1:
                res.append('_')
            elif run == 2:
                res.append('__')
            else:
                res.append('-')
            i = j
    return ''.join(res)


# ---- explicit spec examples ----
def test_example_no_spaces():
    assert fix_spaces("Example") == "Example"

def test_example_single_space():
    assert fix_spaces("Example 1") == "Example_1"

def test_example_leading_single_space():
    assert fix_spaces(" Example 2") == "_Example_2"

def test_example_triple_spaces_become_dash():
    assert fix_spaces(" Example   3") == "_Example-3"


def test_empty_string():
    assert fix_spaces("") == ""

def test_single_space_becomes_underscore():
    assert fix_spaces(" ") == "_"

def test_double_space_becomes_two_underscores():
    assert fix_spaces("  ") == "__"

def test_triple_space_becomes_single_dash():
    assert fix_spaces("   ") == "-"

def test_quad_space_becomes_single_dash():
    assert fix_spaces("    ") == "-"

def test_five_spaces_become_single_dash():
    assert fix_spaces("     ") == "-"

def test_six_spaces_become_single_dash():
    assert fix_spaces("      ") == "-"

def test_many_spaces_become_single_dash():
    assert fix_spaces(" " * 10) == "-"
    assert fix_spaces(" " * 100) == "-"

def test_spaces_between_chars_single():
    assert fix_spaces("a b") == "a_b"

def test_spaces_between_chars_double():
    assert fix_spaces("a  b") == "a__b"

def test_spaces_between_chars_triple():
    assert fix_spaces("a   b") == "a-b"

def test_spaces_between_chars_long_run():
    for n in [3, 4, 5, 6, 7, 8, 10, 20]:
        assert fix_spaces("a" + " " * n + "b") == "a-b", f"n={n}"

def test_original_underscores_preserved_no_spaces():
    assert fix_spaces("a_b") == "a_b"
    assert fix_spaces("a__b") == "a__b"
    assert fix_spaces("a___b") == "a___b"
    assert fix_spaces("___") == "___"
    assert fix_spaces("____") == "____"
    assert fix_spaces("_") == "_"

def test_original_underscores_not_confused_with_spaces():
    # three literal underscores must NOT become a dash
    assert fix_spaces("Example___1") == "Example___1"

def test_mixed_underscores_and_spaces():
    # underscore adjacent to space-run should be preserved
    assert fix_spaces("a_   b") == reference_fix_spaces("a_   b") == "a_-b"
    assert fix_spaces("a___   b") == "a___-b"
    assert fix_spaces("a   ___b") == "a-___b"

def test_leading_trailing_runs():
    assert fix_spaces("   Example") == "-Example"
    assert fix_spaces("Example   ") == "Example-"
    assert fix_spaces("    Example    ") == "-Example-"
    assert fix_spaces("  Example  ") == "__Example__"

def test_multiple_runs_independent():
    assert fix_spaces("a   b c  d    e") == "a-b_c__d-e"
    assert fix_spaces("a  b   c    d") == "a__b-c-d"
    assert fix_spaces("   a  b   c ") == "-a__b-c-"

def test_dashes_in_input_preserved():
    assert fix_spaces("a-b") == "a-b"
    assert fix_spaces("a- b") == "a-_b"
    assert fix_spaces("a   -b") == "a--b"

def test_output_never_contains_space():
    assert " " not in fix_spaces("a b   c  d    e f")
    assert " " not in fix_spaces("   ")
    assert " " not in fix_spaces(" a ")


@given(st.text(alphabet=st.sampled_from(["a", "b", " ", "_", "-", "E"]), min_size=0, max_size=20))
def test_property_no_space_in_output(s):
    assert " " not in fix_spaces(s)

@given(st.text(alphabet=st.sampled_from(["a", "b", "E", "_", "-"]), min_size=0, max_size=20))
def test_property_no_spaces_means_identity(s):
    # no spaces -> output must equal input exactly
    assert " " not in s
    assert fix_spaces(s) == s

@given(st.text(alphabet=st.sampled_from(["a", "b", " "]), min_size=0, max_size=15))
def test_property_equivalence_to_reference_model(s):
    assert fix_spaces(s) == reference_fix_spaces(s)

@given(st.text(alphabet=st.sampled_from(["a", " ", "_", "-", "1", "2"]), min_size=0, max_size=20))
def test_property_equivalence_to_reference_model_with_underscores_dashes(s):
    assert fix_spaces(s) == reference_fix_spaces(s)

@given(st.integers(min_value=3, max_value=30))
def test_property_any_long_run_collapses_to_single_dash(n):
    assert fix_spaces("a" + " " * n + "b") == "a-b"

@given(st.integers(min_value=3, max_value=30))
def test_property_only_spaces_collapses_to_single_dash(n):
    assert fix_spaces(" " * n) == "-"

@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=1, max_size=5))
def test_property_single_space_always_single_underscore(word):
    assert fix_spaces(word + " " + word) == word + "_" + word

@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=1, max_size=5))
def test_property_double_space_always_double_underscore(word):
    assert fix_spaces(word + "  " + word) == word + "__" + word

@given(st.text(alphabet=st.sampled_from(["a", "b"]), min_size=0, max_size=10).filter(lambda s: "   " not in s))
def test_property_short_runs_match_simple_replace(s):
    # when no run >=3 exists, spec reduces to plain replace
    assert fix_spaces(s) == s.replace(" ", "_")
